 display:flex;flex-direction:column;min-height:540px;
 height:clamp(540px,calc(100dvh - 140px),910px);
 width:100%;max-width:100%;margin:10px 0;
 overflow:hidden;border:1px solid #43556a;border-radius:10px;
 background:#101825;color:var(--musical-fg);
 font:12px/1.35 system-ui,-apple-system,sans-serif;
