}
.huw-musical--workspace .huw-musical-links a{
 display:inline-flex;align-items:center;height:29px;min-width:0;white-space:nowrap;
 text-decoration:none;padding:5px 7px;border-radius:6px;
 border:1px solid #485e73;background:#25354b;color:#c6e8f8;font:inherit
}
