.huw-musical--workspace .huw-musical-layout{
 flex:0 0 var(--musical-preview-height);height:var(--musical-preview-height);
 min-height:0;max-height:none;display:grid;
 grid-template-columns:minmax(0,1fr) minmax(0,1fr);
 overflow:hidden;border-bottom:0;background:#0f1723
}
.huw-musical--workspace[data-preview-mode="stage"] .huw-musical-layout{grid-template-columns:1fr}
