.huw-musical--workspace .huw-musical-stage,
.huw-musical--workspace .huw-musical-score{
 min-height:0;height:100%;min-width:0;margin:0;padding:7px 9px;
 display:flex;flex-direction:column;overflow:hidden
}
.huw-musical--workspace .huw-musical-stage{background:#0c1421;border-right:1px solid #344458}
