.huw-musical--workspace .huw-musical-track-filters{display:flex;align-items:center;gap:3px;min-width:0}
.huw-musical--workspace .huw-musical-timeline-toolbar button{
 padding:4px 7px;min-height:25px;border-radius:5px;border:1px solid transparent;
