}
.huw-musical--workspace .huw-musical-timeline-toolbar button:hover{background:#2e455e;color:#fff}
.huw-musical--workspace .huw-musical-timeline-toolbar button.is-active{
 border-color:#47758f;background:#24526e;color:#e3f9ff
}
.huw-musical--workspace .huw-musical-timeline-toolbar button:disabled{opacity:.4;cursor:not-allowed}
.huw-musical--workspace .huw-musical-edit-controls{display:flex;gap:3px;align-items:center;margin-left:auto}
.huw-musical--workspace .huw-musical-edit-controls button{border:1px solid #40576e;background:#25384f}
.huw-musical--workspace .huw-musical-edit-controls .huw-musical-zoom-in,
.huw-musical--workspace .huw-musical-edit-controls .huw-musical-zoom-out{
 font-size:16px;line-height:12px;padding:5px 9px
}
.huw-musical--workspace .huw-musical-editor{
 display:flex;flex-direction:column;flex:1 1 auto;min-height:0;min-width:0;overflow:hidden;
 margin:0;padding:0;background:#121d2d;border:0;border-radius:0
}
.huw-musical--workspace .huw-musical-legacy-heading,
.huw-musical--workspace .huw-musical-legacy-help{display:none!important}
.huw-musical--workspace .huw-musical-tracks{
 --musical-zoom:1;display:block;flex:1 1 auto;min-height:0;
 max-height:none;width:100%;overflow:auto;border:0;border-radius:0;
 background:#101a29;scrollbar-width:thin;overscroll-behavior:contain
}
.huw-musical--workspace .huw-musical-timeline-ruler{
 display:grid;grid-template-columns:var(--musical-track-label-width) minmax(0,1fr);
 position:sticky;top:0;z-index:9;width:calc(100% * var(--musical-zoom));
 min-width:640px;height:27px;background:#223248;border-bottom:1px solid #4d6278;
 font-size:10px;color:#e4edf8
}
