 position:sticky;left:0;z-index:11;padding:5px 8px;
 border-right:1px solid #465c71;background:#223248;color:#b9cedb
}
.huw-musical--workspace .huw-musical-ruler-lane{
 position:relative;min-width:0;cursor:crosshair;
 background:repeating-linear-gradient(90deg,transparent 0,transparent calc(10% - 1px),#ffffff12 calc(10% - 1px),#ffffff12 10%)
}
.huw-musical--workspace .huw-musical-ruler-tick{
 position:absolute;top:0;font-variant-numeric:tabular-nums;
