}
.huw-musical--workspace .huw-musical-track{
 display:grid;grid-template-columns:var(--musical-track-label-width) minmax(0,1fr);
 width:calc(100% * var(--musical-zoom));min-width:640px;min-height:39px;height:39px;
 border-bottom:1px solid #2a3b4d;background:#142033
}
